<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: rgba(255, 255, 255, 0.9);
        --surface-strong: #ffffff;
        --text: #142033;
        --muted: #5b677a;
        --border: #dbe3ef;
        --accent: #4f7cff;
        --accent-soft: #eaf0ff;
        --shadow: 0 16px 40px rgba(20, 32, 51, 0.08);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #ffffff 0, transparent 38%),
          linear-gradient(180deg, #eef3ff 0%, var(--bg) 100%);
      }

      main {
        width: min(920px, calc(100% - 32px));
        margin: 0 auto;
        padding: 64px 0 80px;
      }

      .hero {
        margin-bottom: 28px;
        padding: 28px;
        border: 1px solid rgba(219, 227, 239, 0.9);
        border-radius: 28px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0.72));
        box-shadow: var(--shadow);
        backdrop-filter: blur(10px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin: 0 0 12px;
        padding: 8px 12px;
        border-radius: 999px;
        color: var(--accent);
        background: var(--accent-soft);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.03em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.1rem, 4vw, 3.5rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lead {
        margin: 14px 0 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-list {
        display: grid;
        gap: 14px;
      }

      .example {
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: var(--surface);
        box-shadow: 0 8px 24px rgba(20, 32, 51, 0.05);
        overflow: hidden;
      }

      .question {
        width: 100%;
        padding: 20px 22px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        border: 0;
        background: transparent;
        color: var(--text);
        font: inherit;
        text-align: left;
        cursor: pointer;
      }

      .question:focus-visible {
        outline: 3px solid rgba(79, 124, 255, 0.35);
        outline-offset: -3px;
      }

      .question-text {
        margin: 0;
        font-size: 1.04rem;
        font-weight: 700;
      }

      .chevron {
        flex: none;
        width: 38px;
        height: 38px;
        display: grid;
        place-items: center;
        border-radius: 999px;
        background: #f3f6ff;
        color: var(--accent);
        transition: transform 180ms ease, background-color 180ms ease;
      }

      .example[data-open="true"] .chevron {
        transform: rotate(180deg);
        background: var(--accent-soft);
      }

      .details {
        padding: 0 22px 22px;
        color: var(--muted);
        line-height: 1.7;
      }

      .details p {
        margin: 0;
      }

      .details[hidden] {
        display: none;
      }

      @media (max-width: 640px) {
        main {
          width: min(100% - 20px, 920px);
          padding-top: 20px;
        }

        .hero,
        .question {
          padding-left: 18px;
          padding-right: 18px;
        }

        .details {
          padding-left: 18px;
          padding-right: 18px;
        }
      }
    </style>
  </head>
  <body>
    <main id="app"></main>

    <script>
      const faqs = [
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep 12 to 16 hours a day, and kittens or senior cats may sleep even more. That marathon nap schedule is normal and helps them conserve energy for short bursts of play.",
        },
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also happen when they're nervous, hurt, or seeking comfort. It's a versatile form of communication, not just a sign of happiness.",
        },
        {
          question: "Do cats need to drink a lot of water?",
          answer:
            "Cats typically drink less than dogs, so encouraging hydration matters. Fresh water, fountains, and wet food can help support healthy drinking habits.",
        },
        {
          question: "How can I keep my cat entertained?",
          answer:
            "Rotate toys, provide scratching posts, and build short play sessions into the day. Cats usually enjoy chasing, stalking, climbing, and puzzle feeders that reward curiosity.",
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is a comforting behavior linked to kittenhood. Adult cats often knead when they feel safe, content, or especially attached to a person or place.",
        },
        {
          question: "What makes a cat-friendly home?",
          answer:
            "Give your cat vertical space, quiet resting spots, clean litter boxes, and predictable routines. A calm environment with room to observe and hide helps cats feel secure.",
        },
      ];

      function createIcon() {
        const span = document.createElement("span");
        span.className = "chevron";
        span.setAttribute("aria-hidden", "true");
        span.textContent = "⌄";
        return span;
      }

      function FAQItem({ question, answer, index }) {
        const section = document.createElement("div");
        section.className = "example";
        section.dataset.open = "false";

        const button = document.createElement("button");
        button.className = "question";
        button.type = "button";
        button.setAttribute("aria-expanded", "false");
        button.setAttribute("aria-controls", `faq-panel-${index}`);

        const text = document.createElement("p");
        text.className = "question-text";
        text.textContent = question;

        button.append(text, createIcon());

        const details = document.createElement("div");
        details.className = "details";
        details.id = `faq-panel-${index}`;
        details.hidden = true;

        const paragraph = document.createElement("p");
        paragraph.textContent = answer;
        details.appendChild(paragraph);

        button.addEventListener("click", () => {
          const isOpen = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isOpen));
          details.hidden = isOpen;
          section.dataset.open = String(!isOpen);
        });

        section.append(button, details);
        return section;
      }

      function App() {
        const container = document.createElement("div");

        const hero = document.createElement("section");
        hero.className = "hero";
        hero.innerHTML = `
          <div class="eyebrow">Cat FAQ</div>
          <h1>Everything you need to know about cats</h1>
          <p class="lead">A clean, modern FAQ with expandable answers and a friendly product-style layout.</p>
        `;

        const list = document.createElement("div");
        list.className = "faq-list";
        faqs.forEach((faq, index) => {
          list.appendChild(FAQItem({ ...faq, index }));
        });

        container.append(hero, list);
        return container;
      }

      document.getElementById("app").appendChild(App());
    </script>
  </body>
</html>
